		globalconf.input.tap_to_click = luaL_checkinteger(L, 2);
	} else if (strcmp(key, "tap_and_drag") == 0) {
		globalconf.input.tap_and_drag = luaL_checkinteger(L, 2);
	} else if (strcmp(key, "drag_lock") == 0) {
