	lua_newtable(L);
	lua_newtable(L);
	lua_pushnumber(L, 0xffeb);
	lua_setfield(L, -2, "keysym");
	lua_rawseti(L, -2, 1);
	lua_setfield(L, -2, "Mod4");

	lua_newtable(L);
	lua_newtable(L);
	lua_pushnumber(L, 0xfe03);
	lua_setfield(L, -2, "keysym");
	lua_rawseti(L, -2, 1);
	lua_setfield(L, -2, "Mod5");

	lua_setfield(L, -2, "_modifiers");

