some_get_button_states(int states[5])
{
	int i;

	if (!states)
		return;

	/* Read from globalconf.button_state which is updated in buttonpress() */
	for (i = 0; i < 5; i++)
		states[i] = globalconf.button_state.buttons[i] ? 1 : 0;
}

