/* Set the keyboard layout group
 * In Wayland, we update the xkb_state directly and notify clients.
 * Returns 1 on success, 0 on failure
 */
int
some_xkb_set_layout_group(xkb_layout_index_t group)
{
	struct xkb_state *xkb_state;
	struct xkb_keymap *keymap;
	xkb_layout_index_t num_layouts;
	xkb_mod_mask_t depressed, latched, locked;
	xkb_layout_index_t old_group;

	if (!kb_group || !kb_group->wlr_group)
		return 0;

	xkb_state = kb_group->wlr_group->keyboard.xkb_state;
	keymap = kb_group->wlr_group->keyboard.keymap;

	if (!xkb_state || !keymap)
		return 0;

	/* Validate group index */
	num_layouts = xkb_keymap_num_layouts(keymap);
	if (group >= num_layouts)
		return 0;

	/* Get current modifier state (preserve it while changing layout) */
	depressed = xkb_state_serialize_mods(xkb_state, XKB_STATE_MODS_DEPRESSED);
	latched = xkb_state_serialize_mods(xkb_state, XKB_STATE_MODS_LATCHED);
	locked = xkb_state_serialize_mods(xkb_state, XKB_STATE_MODS_LOCKED);

	/* Get current group for comparison */
	old_group = xkb_state_serialize_layout(xkb_state, XKB_STATE_LAYOUT_EFFECTIVE);

	/* Update xkb_state with new layout group (locked layout) */
	xkb_state_update_mask(xkb_state,
		depressed, latched, locked,  /* preserve modifiers */
		0,      /* depressed_layout */
		0,      /* latched_layout */
		group); /* locked_layout = new layout */

	/* Sync the keyboard's modifiers struct with the new xkb_state.
	 * wlr_keyboard only updates this struct internally when processing
	 * key events, so after manual xkb_state_update_mask() we must do
	 * it ourselves, otherwise clients receive stale group=0. */
	struct wlr_keyboard *kbd = &kb_group->wlr_group->keyboard;
	kbd->modifiers.depressed = xkb_state_serialize_mods(xkb_state,
		XKB_STATE_MODS_DEPRESSED);
	kbd->modifiers.latched = xkb_state_serialize_mods(xkb_state,
		XKB_STATE_MODS_LATCHED);
	kbd->modifiers.locked = xkb_state_serialize_mods(xkb_state,
		XKB_STATE_MODS_LOCKED);
	kbd->modifiers.group = xkb_state_serialize_layout(xkb_state,
		XKB_STATE_LAYOUT_EFFECTIVE);

	/* Also update all member keyboards' xkb_state and modifiers.group.
	 * Without this, the next key event from a member keyboard triggers
	 * handle_keyboard_modifiers() which reads the member's stale group=0
	 * and overwrites our change on the group's virtual keyboard. */
	int member_count = 0;
	struct kb_group_device *dev;
	wl_list_for_each(dev, &kb_group->wlr_group->devices, link) {
		struct wlr_keyboard *member = dev->keyboard;
		if (member->xkb_state) {
			xkb_mod_mask_t m_dep = xkb_state_serialize_mods(
				member->xkb_state, XKB_STATE_MODS_DEPRESSED);
			xkb_mod_mask_t m_lat = xkb_state_serialize_mods(
				member->xkb_state, XKB_STATE_MODS_LATCHED);
			xkb_mod_mask_t m_loc = xkb_state_serialize_mods(
				member->xkb_state, XKB_STATE_MODS_LOCKED);
			xkb_state_update_mask(member->xkb_state,
				m_dep, m_lat, m_loc, 0, 0, group);
			member->modifiers.group = group;
			member_count++;
		}
	}
	wlr_log(WLR_DEBUG, "[XKB-DEBUG] set_layout_group(%d): %d member keyboards updated, "
		"group_kbd.modifiers.group=%d",
		(int)group, member_count, (int)kbd->modifiers.group);

	/* Set the keyboard on the seat and notify clients */
	wlr_seat_set_keyboard(seat, kbd);
	wlr_seat_keyboard_notify_modifiers(seat, &kbd->modifiers);

	/* Emit signal if layout actually changed */
	if (old_group != group) {
		globalconf.xkb.last_group = group;
		xkb_schedule_group_changed();
	}

	return 1;
}

/* Get the XKB group names/symbols string.
 * Returns a static buffer with format like "pc+us+cz(qwerty):2+grp:alt_shift_toggle".
 * Uses RMLVO short codes (e.g. "us", "cz") so the keyboardlayout widget
 * can look them up in its xkeyboard_country_code table.
 */
const char *
some_xkb_get_group_names(void)
{
	static char symbols_buffer[512];
	size_t offset = 0;

	if (!kb_group || !kb_group->wlr_group)
		return NULL;

	if (!kb_group->wlr_group->keyboard.keymap)
		return NULL;

	/* Start with "pc" prefix (matches XKB convention) */
	offset = snprintf(symbols_buffer, sizeof(symbols_buffer), "pc");

	const char *layout_str = globalconf.keyboard.xkb_layout;
	const char *variant_str = globalconf.keyboard.xkb_variant;

	if (layout_str && *layout_str) {
		/* Build from RMLVO components: short codes that the widget expects.
		 * Layout string is comma-separated, e.g. "us,cz"
		 * Variant string is comma-separated, e.g. ",qwerty" (empty = no variant) */
		char layout_buf[256], variant_buf[256];
		char *layouts[32], *variants[32];
		int nlayouts = 0, nvariants = 0;
		char *p, *comma;

		snprintf(layout_buf, sizeof(layout_buf), "%s", layout_str);
		snprintf(variant_buf, sizeof(variant_buf), "%s",
		         variant_str ? variant_str : "");

		/* Split layouts by comma */
		p = layout_buf;
		while (nlayouts < 32) {
			layouts[nlayouts++] = p;
			comma = strchr(p, ',');
			if (!comma) break;
			*comma = '\0';
			p = comma + 1;
		}

		/* Split variants by comma (preserving empty fields) */
		p = variant_buf;
		while (nvariants < 32) {
			variants[nvariants++] = p;
			comma = strchr(p, ',');
			if (!comma) break;
			*comma = '\0';
			p = comma + 1;
		}

		for (int i = 0; i < nlayouts && offset < sizeof(symbols_buffer) - 1; i++) {
			const char *variant = (i < nvariants) ? variants[i] : "";
			int has_variant = variant && *variant;
			int group_idx = i + 1;

			if (has_variant && i > 0)
				offset += snprintf(symbols_buffer + offset,
				                   sizeof(symbols_buffer) - offset,
				                   "+%s(%s):%d", layouts[i], variant, group_idx);
			else if (has_variant)
				offset += snprintf(symbols_buffer + offset,
				                   sizeof(symbols_buffer) - offset,
				                   "+%s(%s)", layouts[i], variant);
			else if (i > 0)
				offset += snprintf(symbols_buffer + offset,
				                   sizeof(symbols_buffer) - offset,
				                   "+%s:%d", layouts[i], group_idx);
			else
				offset += snprintf(symbols_buffer + offset,
				                   sizeof(symbols_buffer) - offset,
				                   "+%s", layouts[i]);
		}
	} else {
		/* No RMLVO layout configured - fall back to keymap layout names */
		struct xkb_keymap *keymap = kb_group->wlr_group->keyboard.keymap;
		xkb_layout_index_t num_layouts = xkb_keymap_num_layouts(keymap);

		for (xkb_layout_index_t i = 0; i < num_layouts &&
		     offset < sizeof(symbols_buffer) - 1; i++) {
			const char *name = xkb_keymap_layout_get_name(keymap, i);
			if (name) {
				offset += snprintf(symbols_buffer + offset,
				                   sizeof(symbols_buffer) - offset,
				                   "+%s", name);
			}
		}
	}

	/* Append XKB options if configured */
	if (globalconf.keyboard.xkb_options &&
	    *globalconf.keyboard.xkb_options &&
	    offset < sizeof(symbols_buffer) - 1) {
		offset += snprintf(symbols_buffer + offset,
		                   sizeof(symbols_buffer) - offset,
		                   "+%s", globalconf.keyboard.xkb_options);
	}

	return symbols_buffer;
}

/* External references needed for keymap rebuild */
extern struct wl_event_loop *some_get_event_loop(void);

/* Rebuild the keyboard keymap from current globalconf settings */
void
some_rebuild_keyboard_keymap(void)
{
	struct xkb_context *context;
	struct xkb_keymap *keymap;
	struct xkb_rule_names rules = {0};

	if (!kb_group || !kb_group->wlr_group)
		return;

	context = xkb_context_new(XKB_CONTEXT_NO_FLAGS);
	if (!context)
		return;

	rules.layout = globalconf.keyboard.xkb_layout;
	rules.variant = globalconf.keyboard.xkb_variant;
	rules.options = globalconf.keyboard.xkb_options;

	keymap = xkb_keymap_new_from_names(context, &rules,
	                                   XKB_KEYMAP_COMPILE_NO_FLAGS);
	if (keymap) {
		xkb_layout_index_t num = xkb_keymap_num_layouts(keymap);
		wlr_log(WLR_DEBUG, "[XKB-DEBUG] rebuild_keymap: layout='%s' variant='%s' "
			"options='%s' -> %d layouts in keymap",
			rules.layout ? rules.layout : "(null)",
			rules.variant ? rules.variant : "(null)",
			rules.options ? rules.options : "(null)",
			(int)num);
		for (xkb_layout_index_t i = 0; i < num; i++) {
			wlr_log(WLR_DEBUG, "[XKB-DEBUG] rebuild_keymap: layout[%d] = '%s'",
				(int)i, xkb_keymap_layout_get_name(keymap, i));
		}
		wlr_keyboard_set_keymap(&kb_group->wlr_group->keyboard, keymap);
		xkb_keymap_unref(keymap);
		xkb_schedule_map_changed();
	} else {
		wlr_log(WLR_ERROR, "[XKB-DEBUG] rebuild_keymap: FAILED to create keymap "
			"for layout='%s' variant='%s'",
			rules.layout ? rules.layout : "(null)",
			rules.variant ? rules.variant : "(null)");
	}

	xkb_context_unref(context);
}

/* Apply keyboard repeat info from current globalconf settings */
void
some_apply_keyboard_repeat_info(void)
{
	if (!kb_group || !kb_group->wlr_group)
		return;

	wlr_keyboard_set_repeat_info(&kb_group->wlr_group->keyboard,
		globalconf.keyboard.repeat_rate, globalconf.keyboard.repeat_delay);
}

/*
 * Layer Surface Focus API
 */

void
layer_surface_grant_keyboard(LayerSurface *ls)
{
	if (!ls || !ls->layer_surface || !ls->mapped)
		return;

	/* Deactivate the focused client */
	focusclient(NULL, 0);

	/* Set as exclusive focus */
	exclusive_focus = ls;

	/* Send keyboard enter to the layer surface */
	client_notify_enter(ls->layer_surface->surface, wlr_seat_get_keyboard(seat));
}

void
layer_surface_revoke_keyboard(LayerSurface *ls)
{
	if (!ls)
		return;

	/* Only revoke if this surface currently has exclusive focus */
	if (exclusive_focus == ls) {
		exclusive_focus = NULL;

		/* Explicitly clear keyboard focus from the layer surface */
		wlr_seat_keyboard_notify_clear_focus(seat);

		/* Refocus the top client on the selected monitor */
		focusclient(focustop(selmon), 1);
	}
}

