 * It properly updates the member's xkb_state, syncs modifiers, and
 * propagates through handle_keyboard_modifiers() to the group keyboard,
 * which then reaches somewm's keypressmod() and the client.
 *
 * Previous approach (manual xkb_state_update_mask + struct patching)
 * failed because wlr_keyboard_notify_key() on the member would later
 * call keyboard_modifier_update() which re-serialized from xkb_state,
 * and the member's xkb_state could drift out of sync.
 *
 * Returns 1 on success, 0 on failure.
 */
int
some_xkb_set_layout_group(xkb_layout_index_t group)
{
	if (!kb_group || !kb_group->wlr_group)
		return 0;

	struct wlr_keyboard *kbd = &kb_group->wlr_group->keyboard;

	if (!kbd->xkb_state || !kbd->keymap)
		return 0;

	/* Validate group index */
	xkb_layout_index_t num_layouts = xkb_keymap_num_layouts(kbd->keymap);
	if (group >= num_layouts)
		return 0;

	xkb_layout_index_t old_group = xkb_state_serialize_layout(
		kbd->xkb_state, XKB_STATE_LAYOUT_EFFECTIVE);

	if (old_group == group)
		return 1; /* Already at requested group */

	/* Update member keyboards via wlr_keyboard_notify_modifiers().
	 * This goes through the proper wlroots path:
	 *   member xkb_state_update_mask → keyboard_modifier_update →
	 *   emit modifiers signal → handle_keyboard_modifiers (group code) →
	 *   sync all members → propagate to group keyboard →
	 *   emit group modifiers signal → somewm keypressmod
	 */
	int member_count = 0;
	struct kb_group_device *dev;
	wl_list_for_each(dev, &kb_group->wlr_group->devices, link) {
		struct wlr_keyboard *member = dev->keyboard;
		if (member->xkb_state) {
			xkb_mod_mask_t dep = xkb_state_serialize_mods(
				member->xkb_state, XKB_STATE_MODS_DEPRESSED);
			xkb_mod_mask_t lat = xkb_state_serialize_mods(
				member->xkb_state, XKB_STATE_MODS_LATCHED);
			xkb_mod_mask_t loc = xkb_state_serialize_mods(
				member->xkb_state, XKB_STATE_MODS_LOCKED);
			/* This calls xkb_state_update_mask internally,
			 * updates member->modifiers, and emits the modifiers
			 * signal which handle_keyboard_modifiers picks up. */
			wlr_keyboard_notify_modifiers(member, dep, lat, loc, group);
			member_count++;
		}
	}

	wlr_log(WLR_DEBUG, "[XKB-DEBUG] set_layout_group(%d): "
		"notified %d member keyboards, "
		"group_kbd.modifiers.group=%d",
		(int)group, member_count, (int)kbd->modifiers.group);

	/* If no members (shouldn't happen), update group keyboard directly */
	if (member_count == 0) {
		xkb_mod_mask_t dep = xkb_state_serialize_mods(
			kbd->xkb_state, XKB_STATE_MODS_DEPRESSED);
		xkb_mod_mask_t lat = xkb_state_serialize_mods(
			kbd->xkb_state, XKB_STATE_MODS_LATCHED);
		xkb_mod_mask_t loc = xkb_state_serialize_mods(
			kbd->xkb_state, XKB_STATE_MODS_LOCKED);
		wlr_keyboard_notify_modifiers(kbd, dep, lat, loc, group);
	}

	/* Notify client of new modifiers via seat */
	wlr_seat_set_keyboard(seat, kbd);
	wlr_seat_keyboard_notify_modifiers(seat, &kbd->modifiers);

	/* Emit Lua signal if layout actually changed */

