	wlr_log(WLR_DEBUG, "[XKB-DEBUG] rebuild_keymap: layout='%s' variant='%s' "
		"options='%s' -> %d layouts in keymap",
		rules.layout ? rules.layout : "(null)",
		rules.variant ? rules.variant : "(null)",
		rules.options ? rules.options : "(null)",
		(int)num);

	/* Set keymap on group keyboard */
	wlr_keyboard_set_keymap(&kb_group->wlr_group->keyboard, keymap);

	/* Also set keymap on all member keyboards.
	 * Without this, members keep their old keymap (e.g. single-layout "us")
	 * while the group keyboard has the new multi-layout keymap.
	 * Layout switching then fails because members can't switch to
	 * a group index that doesn't exist in their keymap. */
	int member_count = 0;
	struct kb_group_device *dev;
	wl_list_for_each(dev, &kb_group->wlr_group->devices, link) {
		if (dev->keyboard->keymap != keymap) {
			wlr_keyboard_set_keymap(dev->keyboard, keymap);
			member_count++;
		}
	}
	wlr_log(WLR_DEBUG, "[XKB-DEBUG] rebuild_keymap: "
		"updated %d member keyboards", member_count);

	xkb_keymap_unref(keymap);
	xkb_schedule_map_changed();
} else {
	wlr_log(WLR_ERROR, "[XKB-DEBUG] rebuild_keymap: FAILED to create keymap "
		"for layout='%s' variant='%s'",
		rules.layout ? rules.layout : "(null)",
		rules.variant ? rules.variant : "(null)");
}

