 29→static void restore_workspaces(struct sway_output *output) {
 30→	// Workspace output priority
 31→	for (int i = 0; i < root->outputs->length; i++) {
 32→		struct sway_output *other = root->outputs->items[i];
 33→		if (other == output) {
 34→			continue;
 35→		}
 36→
 37→		for (int j = 0; j < other->workspaces->length; j++) {
 38→			struct sway_workspace *ws = other->workspaces->items[j];
 39→			struct sway_output *highest =
 40→				workspace_output_get_highest_available(ws);
 41→			if (highest == output) {
 42→				workspace_detach(ws);
 43→				output_add_workspace(output, ws);
 44→				ipc_event_workspace(NULL, ws, "move");
 45→				j--;
 46→			}
 47→		}
 48→
 49→		if (other->workspaces->length == 0) {
 50→			char *next = workspace_next_name(other->wlr_output->name);
 51→			struct sway_workspace *ws = workspace_create(other, next);
 52→			free(next);
 53→			ipc_event_workspace(NULL, ws, "init");
 54→		}
 55→	}
 56→
 57→	// Saved workspaces
 58→	while (root->fallback_output->workspaces->length) {
 59→		struct sway_workspace *ws = root->fallback_output->workspaces->items[0];
 60→		workspace_detach(ws);
 61→		output_add_workspace(output, ws);
 62→
 63→		// If the floater was made floating while on the NOOP output, its width
 64→		// and height will be zero and it should be reinitialized as a floating
 65→		// container to get the appropriate size and location. Additionally, if
 66→		// the floater is wider or taller than the output or is completely
 67→		// outside of the output's bounds, do the same as the output layout has
 68→		// likely changed and the maximum size needs to be checked and the
 69→		// floater re-centered
 70→		for (int i = 0; i < ws->floating->length; i++) {
 71→			struct sway_container *floater = ws->floating->items[i];
 72→			if (floater->pending.width == 0 || floater->pending.height == 0 ||
 73→					floater->pending.width > output->width ||
 74→					floater->pending.height > output->height ||
 75→					floater->pending.x > output->lx + output->width ||
 76→					floater->pending.y > output->ly + output->height ||
 77→					floater->pending.x + floater->pending.width < output->lx ||
 78→					floater->pending.y + floater->pending.height < output->ly) {
 79→				container_floating_resize_and_center(floater);
 80→			}
 81→		}
 82→
 83→		ipc_event_workspace(NULL, ws, "move");
 84→	}
 85→
 86→	output_sort_workspaces(output);
 87→}
