185→static void evacuate_sticky(struct sway_workspace *old_ws,
186→		struct sway_output *new_output) {
187→	struct sway_workspace *new_ws = output_get_active_workspace(new_output);
188→	if (!sway_assert(new_ws, "New output does not have a workspace")) {
189→		return;
190→	}
191→	while(old_ws->floating->length) {
192→		struct sway_container *sticky = old_ws->floating->items[0];
193→		container_detach(sticky);
194→		workspace_add_floating(new_ws, sticky);
195→		container_handle_fullscreen_reparent(sticky);
196→		container_floating_move_to_center(sticky);
197→		ipc_event_window(sticky, "move");
198→	}
199→	workspace_detect_urgent(new_ws);
