202→static void output_evacuate(struct sway_output *output) {
203→	if (!output->workspaces->length) {
204→		return;
205→	}
206→	struct sway_output *fallback_output = NULL;
207→	if (root->outputs->length > 0) {
208→		fallback_output = root->outputs->items[0];
209→	}
210→
211→	while (output->workspaces->length) {
212→		struct sway_workspace *workspace = output->workspaces->items[0];
213→
214→		workspace_detach(workspace);
215→
216→		struct sway_output *new_output =
217→			workspace_output_get_highest_available(workspace);
218→		if (!new_output) {
219→			new_output = fallback_output;
220→		}
221→		if (!new_output) {
222→			new_output = root->fallback_output;
223→		}
224→
225→		struct sway_workspace *new_output_ws =
226→			output_get_active_workspace(new_output);
227→
228→		if (workspace_is_empty(workspace)) {
229→			// If the new output has an active workspace (the noop output may
230→			// not have one), move all sticky containers to it
231→			if (new_output_ws &&
232→					workspace_num_sticky_containers(workspace) > 0) {
233→				evacuate_sticky(workspace, new_output);
234→			}
235→
236→			if (workspace_num_sticky_containers(workspace) == 0) {
237→				workspace_begin_destroy(workspace);
238→				continue;
239→			}
240→		}
241→
242→		workspace_output_add_priority(workspace, new_output);
243→		output_add_workspace(new_output, workspace);
244→		output_sort_workspaces(new_output);
245→		ipc_event_workspace(NULL, workspace, "move");
246→
247→		// If there is an old workspace (the noop output may not have one),
248→		// check to see if it is empty and should be destroyed.
249→		if (new_output_ws) {
250→			workspace_consider_destroy(new_output_ws);
251→		}
252→	}
253→}
