382→
383→	if (isdigit(a->name[0]) && isdigit(b->name[0])) {
384→		int a_num = strtol(a->name, NULL, 10);
385→		int b_num = strtol(b->name, NULL, 10);
386→		return (a_num < b_num) ? -1 : (a_num > b_num);
387→	} else if (isdigit(a->name[0])) {
388→		return -1;
389→	} else if (isdigit(b->name[0])) {
390→		return 1;
391→	}
392→	return 0;
393→}
