481→static void handle_request_state(struct wl_listener *listener, void *data) {
482→	struct sway_output *output =
483→		wl_container_of(listener, output, request_state);
484→	const struct wlr_output_event_request_state *event = data;
485→	const struct wlr_output_state *state = event->state;
486→
487→	// Store the requested changes so that the active configuration is
488→	// consistent with the current state, and to avoid duplicate logic to apply
489→	// the changes.
490→	struct output_config *oc = new_output_config(output->wlr_output->name);
491→	if (!oc) {
492→		sway_log(SWAY_ERROR, "Allocation failed");
493→		return;
494→	}
495→
496→	int committed = state->committed;
497→	if (committed & WLR_OUTPUT_STATE_MODE) {
498→		if (state->mode != NULL) {
499→			oc->width = state->mode->width;
500→			oc->height = state->mode->height;
501→			oc->refresh_rate = state->mode->refresh / 1000.f;
502→		} else {
503→			oc->width = state->custom_mode.width;
504→			oc->height = state->custom_mode.height;
505→			oc->refresh_rate = state->custom_mode.refresh / 1000.f;
506→		}
507→		committed &= ~WLR_OUTPUT_STATE_MODE;
508→	}
509→	if (committed & WLR_OUTPUT_STATE_SCALE) {
510→		oc->scale = state->scale;
511→		committed &= ~WLR_OUTPUT_STATE_SCALE;
512→	}
513→	if (committed & WLR_OUTPUT_STATE_TRANSFORM) {
514→		oc->transform = state->transform;
515→		committed &= ~WLR_OUTPUT_STATE_TRANSFORM;
516→	}
517→
518→	// We do not expect or support any other changes here
519→	assert(committed == 0);
520→	store_output_config(oc);
521→
522→	force_modeset();
523→}
