634→static void output_manager_apply(struct sway_server *server,
635→		struct wlr_output_configuration_v1 *cfg, bool test_only) {
636→	bool ok = false;
637→	size_t configs_len = config->output_configs->length + wl_list_length(&cfg->heads);
638→	struct output_config **configs = calloc(configs_len, sizeof(*configs));
639→	if (!configs) {
640→		sway_log(SWAY_ERROR, "Allocation failed");
641→		goto error;
642→	}
643→	size_t start_new_configs = config->output_configs->length;
644→	for (size_t idx = 0; idx < start_new_configs; idx++) {
645→		configs[idx] = config->output_configs->items[idx];
646→	}
647→
648→	size_t config_idx = start_new_configs;
649→	struct wlr_output_configuration_head_v1 *config_head;
650→	wl_list_for_each(config_head, &cfg->heads, link) {
651→		// Generate the configuration and store it as a temporary
652→		// config. We keep a record of it so we can remove it later.
653→		struct output_config *oc = output_config_for_config_head(config_head);
654→		if (!oc) {
655→			sway_log(SWAY_ERROR, "Allocation failed");
656→			goto error_config;
657→		}
658→		configs[config_idx++] = oc;
659→	}
660→
661→	// Try to commit without degrade to off enabled. Note that this will fail
662→	// if any output configured for enablement fails to be enabled, even if it
663→	// was not part of the config heads we were asked to configure.
664→	ok = apply_output_configs(configs, configs_len, test_only, false);
665→
666→error_config:
667→	for (size_t idx = start_new_configs; idx < configs_len; idx++) {
668→		struct output_config *cfg = configs[idx];
669→		if (!test_only && ok) {
670→			store_output_config(cfg);
671→		} else {
672→			free_output_config(cfg);
673→		}
674→	}
675→	free(configs);
676→
677→error:
678→	if (ok) {
679→		wlr_output_configuration_v1_send_succeeded(cfg);
680→		if (server->delayed_modeset != NULL) {
681→			wl_event_source_remove(server->delayed_modeset);
682→			server->delayed_modeset = NULL;
683→		}
684→	} else {
685→		wlr_output_configuration_v1_send_failed(cfg);
686→	}
687→	wlr_output_configuration_v1_destroy(cfg);
688→}
