 91→		// Arbitrary lower bound for window size
 92→		if (child->pending.width < 10 || child->pending.height < 10) {
 93→			child->pending.width = 0;
 94→			child->pending.height = 0;
 95→		}
 96→		child_x += child->pending.width + inner_gap;
 97→	}
 98→}
