1179→static bool _spawn_swaybg(char **command) {
1180→	if (config->swaybg_client != NULL) {
1181→		wl_client_destroy(config->swaybg_client);
1182→	}
1183→	int sockets[2];
1184→	if (socketpair(AF_UNIX, SOCK_STREAM, 0, sockets) != 0) {
1185→		sway_log_errno(SWAY_ERROR, "socketpair failed");
1186→		return false;
1187→	}
1188→	if (!sway_set_cloexec(sockets[0], true) || !sway_set_cloexec(sockets[1], true)) {
1189→		return false;
1190→	}
1191→
1192→	config->swaybg_client = wl_client_create(server.wl_display, sockets[0]);
1193→	if (config->swaybg_client == NULL) {
1194→		sway_log_errno(SWAY_ERROR, "wl_client_create failed");
1195→		return false;
1196→	}
1197→
1198→	config->swaybg_client_destroy.notify = handle_swaybg_client_destroy;
1199→	wl_client_add_destroy_listener(config->swaybg_client,
1200→		&config->swaybg_client_destroy);
1201→
1202→	pid_t pid = fork();
1203→	if (pid < 0) {
1204→		sway_log_errno(SWAY_ERROR, "fork failed");
1205→		return false;
1206→	} else if (pid == 0) {
1207→		if (!sway_set_cloexec(sockets[1], false)) {
1208→			_exit(EXIT_FAILURE);
1209→		}
1210→
1211→		char wayland_socket_str[16];
1212→		snprintf(wayland_socket_str, sizeof(wayland_socket_str),
1213→			"%d", sockets[1]);
1214→		setenv("WAYLAND_SOCKET", wayland_socket_str, true);
1215→
1216→		execvp(command[0], command);
1217→		sway_log_errno(SWAY_ERROR, "failed to execute '%s' "
1218→			"(background configuration probably not applied)",
1219→			command[0]);
1220→		_exit(EXIT_FAILURE);
1221→	}
1222→
1223→	if (close(sockets[1]) != 0) {
1224→		sway_log_errno(SWAY_ERROR, "close failed");
1225→		return false;
1226→	}
1227→	return true;
1228→}
