632→static bool finalize_output_config(struct output_config *oc, struct sway_output *output,
633→		const struct wlr_output_state *applied, const struct config_output_state *config_applied) {
634→	if (output == root->fallback_output) {
635→		return false;
636→	}
637→
638→	struct wlr_output *wlr_output = output->wlr_output;
639→	if (oc && !oc->enabled) {
640→		sway_log(SWAY_DEBUG, "Disabling output %s", oc->name);
641→		if (output->enabled) {
642→			output_disable(output);
643→			wlr_output_layout_remove(root->output_layout, wlr_output);
644→		}
645→		return true;
646→	}
647→
648→	enum scale_filter_mode scale_filter_old = output->scale_filter;
649→	enum scale_filter_mode scale_filter_new = oc ? oc->scale_filter : SCALE_FILTER_DEFAULT;
650→	switch (scale_filter_new) {
651→		case SCALE_FILTER_DEFAULT:
652→		case SCALE_FILTER_SMART:
653→			output->scale_filter = ceilf(wlr_output->scale) == wlr_output->scale ?
654→				SCALE_FILTER_NEAREST : SCALE_FILTER_LINEAR;
655→			break;
656→		case SCALE_FILTER_LINEAR:
657→		case SCALE_FILTER_NEAREST:
658→			output->scale_filter = scale_filter_new;
659→			break;
660→	}
661→	if (scale_filter_old != output->scale_filter) {
662→		sway_log(SWAY_DEBUG, "Set %s scale_filter to %s", oc->name,
663→			sway_output_scale_filter_to_string(output->scale_filter));
664→		wlr_damage_ring_add_whole(&output->scene_output->damage_ring);
665→	}
666→
667→	// Find position for it
668→	if (oc && oc->x != INT_MAX && oc->y != INT_MAX) {
669→		sway_log(SWAY_DEBUG, "Set %s position to %d, %d", oc->name, oc->x, oc->y);
670→		wlr_output_layout_add(root->output_layout, wlr_output, oc->x, oc->y);
671→	} else {
672→		wlr_output_layout_add_auto(root->output_layout, wlr_output);
673→	}
674→
675→	if (!output->enabled) {
676→		output_enable(output);
677→	}
678→
679→	wlr_color_transform_unref(output->color_transform);
680→	if (config_applied->color_transform != NULL) {
681→		wlr_color_transform_ref(config_applied->color_transform);
682→	}
683→	output->color_transform = config_applied->color_transform;
684→
685→	output->max_render_time = oc && oc->max_render_time > 0 ? oc->max_render_time : 0;
686→	output->allow_tearing = oc && oc->allow_tearing > 0;
687→	output->hdr = applied->image_description != NULL;
688→
689→	return true;
690→}
