762→		const struct wlr_output_state *state) {
763→	uint32_t unchanged = output_compare_state(output, state);
764→
765→	// Create a shallow copy of the state with only the fields which have been
766→	// changed and potentially a new buffer.
767→	struct wlr_output_state pending = *state;
768→	pending.committed &= ~unchanged;
769→
770→	if (!output_basic_test(output, &pending)) {
771→		wlr_log(WLR_ERROR, "Basic output test failed for %s", output->name);
772→		return false;
773→	}
774→
775→	bool new_back_buffer = false;
776→	if (!output_ensure_buffer(output, &pending, &new_back_buffer)) {
777→		return false;
778→	}
779→
780→	if (!output_prepare_commit(output, &pending)) {
781→		return false;
782→	}
783→
784→	if (!output->impl->commit(output, &pending)) {
785→		if (new_back_buffer) {
786→			wlr_buffer_unlock(pending.buffer);
787→		}
788→		return false;
789→	}
790→
791→	output_apply_commit(output, &pending);
792→	output_send_commit_event(output, &pending);
793→
794→	if (new_back_buffer) {
795→		wlr_buffer_unlock(pending.buffer);
796→	}
797→
798→	return true;
799→}
