611→		const struct wlr_drm_device_state *state,
612→		uint32_t flags, bool test_only) {
613→	// Disallow atomic-only flags
614→	assert((flags & ~DRM_MODE_PAGE_FLIP_FLAGS) == 0);
615→
616→	struct wlr_drm_page_flip *page_flip = NULL;
617→	if (flags & DRM_MODE_PAGE_FLIP_EVENT) {
618→		page_flip = drm_page_flip_create(drm, state);
619→		if (page_flip == NULL) {
620→			return false;
621→		}
622→		page_flip->async = (flags & DRM_MODE_PAGE_FLIP_ASYNC);
623→	}
624→
625→	bool ok = drm->iface->commit(drm, state, page_flip, flags, test_only);
626→	if (ok && !test_only) {
627→		for (size_t i = 0; i < state->connectors_len; i++) {
628→			drm_connector_apply_commit(&state->connectors[i], page_flip);
629→		}
630→	} else {
631→		for (size_t i = 0; i < state->connectors_len; i++) {
632→			drm_connector_rollback_commit(&state->connectors[i]);
633→		}
634→		drm_page_flip_destroy(page_flip);
635→	}
636→	return ok;
637→}
