  1→/*
  2→ * somewm_types.h - Type definitions for somewm compositor
  3→ *
  4→ * This file contains struct definitions and types that were previously
  5→ * embedded in somewm.c. These are now exposed to allow external modules
  6→ * (like Lua bindings) to reference and manipulate somewm data structures.
  7→ */
  8→#ifndef SOMEWM_TYPES_H
  9→#define SOMEWM_TYPES_H
 10→
 11→#include <wayland-server-core.h>
 12→#include <wlr/types/wlr_cursor.h>
 13→#include <wlr/types/wlr_keyboard_group.h>
 14→#include <wlr/types/wlr_layer_shell_v1.h>
 15→#include <wlr/types/wlr_output.h>
 16→#include <wlr/types/wlr_pointer_constraints_v1.h>
 17→#include <wlr/types/wlr_scene.h>
 18→#include <wlr/types/wlr_session_lock_v1.h>
 19→#include <wlr/types/wlr_xdg_decoration_v1.h>
 20→#include <wlr/types/wlr_xdg_shell.h>
 21→#include <xkbcommon/xkbcommon.h>
 22→
 23→#ifdef XWAYLAND
 24→#include <wlr/xwayland.h>
 25→#endif
 26→
 27→/* Enums */
 28→/* NOTE: CurMove and CurResize removed - move/resize now handled by Lua mousegrabber
 29→ * (awful.mouse.client.move/resize) instead of C-level cursor_mode state machine */
 30→enum { CurNormal, CurPressed }; /* cursor */
 31→enum { XDGShell, LayerShell, X11 }; /* client types */
 32→enum { LyrBg, LyrBottom, LyrTile, LyrFloat, LyrWibox, LyrTop, LyrFS, LyrOverlay, LyrBlock, NUM_LAYERS }; /* scene layers */
 33→
 34→/* Window types (for stacking and EWMH) - AwesomeWM compatibility */
 35→typedef enum {
 36→	WINDOW_TYPE_NORMAL,
 37→	WINDOW_TYPE_DESKTOP,
 38→	WINDOW_TYPE_DOCK,
 39→	WINDOW_TYPE_TOOLBAR,
 40→	WINDOW_TYPE_MENU,
 41→	WINDOW_TYPE_UTILITY,
 42→	WINDOW_TYPE_SPLASH,
 43→	WINDOW_TYPE_DIALOG,
 44→	WINDOW_TYPE_DROPDOWN_MENU,
 45→	WINDOW_TYPE_POPUP_MENU,
 46→	WINDOW_TYPE_TOOLTIP,
 47→	WINDOW_TYPE_NOTIFICATION,
 48→	WINDOW_TYPE_COMBO,
 49→	WINDOW_TYPE_DND
 50→} window_type_t;
 51→
 52→/* Size hint flags (ICCCM compatibility) */
 53→enum {
 54→	SIZE_HINT_P_MIN_SIZE    = (1 << 0),
 55→	SIZE_HINT_P_MAX_SIZE    = (1 << 1),
 56→	SIZE_HINT_P_RESIZE_INC  = (1 << 2),
 57→	SIZE_HINT_P_ASPECT      = (1 << 3),
 58→	SIZE_HINT_BASE_SIZE     = (1 << 4),
 59→	SIZE_HINT_P_WIN_GRAVITY = (1 << 5)
 60→};
 61→
 62→/* Forward declarations */
 63→typedef struct Monitor Monitor;
 64→typedef struct client_t client_t;  /* AwesomeWM client struct */
