3429→void
3430→motionnotify(uint32_t time, struct wlr_input_device *device, double dx, double dy,
3431→		double dx_unaccel, double dy_unaccel)
3432→{
3433→	double sx = 0, sy = 0, sx_confined, sy_confined;
3434→	Client *c = NULL, *w = NULL;
3435→	LayerSurface *l = NULL;
3436→	struct wlr_surface *surface = NULL;
3437→
3438→	/* Find the client under the pointer and send the event along. */
3439→	xytonode(cursor->x, cursor->y, &surface, &c, NULL, NULL, NULL, &sx, &sy);
3440→
3441→	if (cursor_mode == CurPressed && !seat->drag
3442→			&& surface != seat->pointer_state.focused_surface
3443→			&& toplevel_from_wlr_surface(seat->pointer_state.focused_surface, &w, &l) >= 0) {
3444→		c = w;
3445→		surface = seat->pointer_state.focused_surface;
3446→		sx = cursor->x - (l ? l->scene->node.x : w->geometry.x);
3447→		sy = cursor->y - (l ? l->scene->node.y : w->geometry.y);
3448→	}
3449→
3450→	/* time is 0 in internal calls meant to restore pointer focus. */
3451→	if (time) {
3452→		wlr_relative_pointer_manager_v1_send_relative_motion(
3453→				relative_pointer_mgr, seat, (uint64_t)time * 1000,
3454→				dx, dy, dx_unaccel, dy_unaccel);
3455→
3456→		/* Note: Constraint selection is done in focusclient(), not here.
3457→		 * dwl/somewm previously iterated all constraints here which caused
3458→		 * the "last constraint wins" bug breaking games like Minecraft. */
3459→
3460→		if (active_constraint) {
3461→			toplevel_from_wlr_surface(active_constraint->surface, &c, NULL);
3462→			if (c && active_constraint->surface == seat->pointer_state.focused_surface) {
3463→				sx = cursor->x - c->geometry.x - c->bw;
3464→				sy = cursor->y - c->geometry.y - c->bw;
3465→				if (wlr_region_confine(&active_constraint->region, sx, sy,
3466→						sx + dx, sy + dy, &sx_confined, &sy_confined)) {
3467→					dx = sx_confined - sx;
3468→					dy = sy_confined - sy;
3469→				}
3470→
3471→				if (active_constraint->type == WLR_POINTER_CONSTRAINT_V1_LOCKED)
3472→					return;
3473→			}
3474→		}
3475→
3476→		wlr_cursor_move(cursor, device, dx, dy);
