587→void
588→arrangelayers(Monitor *m)
589→{
590→	int i;
591→	struct wlr_box usable_area = m->m;
592→	LayerSurface *l;
593→	uint32_t layers_above_shell[] = {
594→		ZWLR_LAYER_SHELL_V1_LAYER_OVERLAY,
595→		ZWLR_LAYER_SHELL_V1_LAYER_TOP,
596→	};
597→	if (!m->wlr_output->enabled)
598→		return;
599→
600→	/* Arrange exclusive surfaces from top->bottom */
601→	for (i = 3; i >= 0; i--)
602→		arrangelayer(m, &m->layers[i], &usable_area, 1);
603→
604→	/* Apply drawin struts (from Lua wibars) to the usable area
605→	 * This must happen AFTER layer shell exclusive zones but BEFORE setting m->w */
606→	some_monitor_apply_drawin_struts(m, &usable_area);
607→
608→	if (!wlr_box_equal(&usable_area, &m->w)) {
609→		lua_State *L;
610→		screen_t *screen;
611→
612→		m->w = usable_area;
613→
614→		/* Update Lua screen.workarea property to match the new usable area
615→		 * This emits property::workarea signal so layouts get the correct workarea */
616→		L = globalconf_get_lua_State();
617→		if (L && globalconf.screens.tab) {
618→			screen = luaA_screen_get_by_monitor(L, m);
619→			if (screen) {
620→				screen_set_workarea(L, screen, &usable_area);
621→			}
622→		}
623→
624→		arrange(m);
625→	}
626→
627→	/* Arrange non-exlusive surfaces from top->bottom */
628→	for (i = 3; i >= 0; i--)
629→		arrangelayer(m, &m->layers[i], &usable_area, 0);
630→
631→	/* Find topmost keyboard interactive layer and emit request::keyboard signal
632→	 * If the layer surface has a Lua object, let Lua decide whether to grant focus.
633→	 * Otherwise, use legacy auto-grant behavior. */
634→	for (i = 0; i < (int)LENGTH(layers_above_shell); i++) {
635→		wl_list_for_each_reverse(l, &m->layers[layers_above_shell[i]], link) {
636→			if (locked || !l->layer_surface->current.keyboard_interactive || !l->mapped)
637→				continue;
638→
639→			if (l->lua_object && globalconf_L) {
640→				/* Emit request::keyboard signal - Lua decides whether to grant focus */
641→				const char *context = (l->layer_surface->current.keyboard_interactive ==
642→					ZWLR_LAYER_SURFACE_V1_KEYBOARD_INTERACTIVITY_EXCLUSIVE)
643→					? "exclusive" : "on_demand";
644→				layer_surface_emit_request_keyboard(l->lua_object, context);
645→				/* If Lua granted focus, we're done. Otherwise, continue searching. */
646→				if (l->lua_object->has_keyboard_focus)
647→					return;
648→			} else {
649→				/* Legacy behavior for surfaces without Lua objects */
650→				focusclient(NULL, 0);
651→				exclusive_focus = l;
652→				client_notify_enter(l->layer_surface->surface, wlr_seat_get_keyboard(seat));
653→				return;
654→			}
655→		}
656→	}
657→}
658→
659→void
660→axisnotify(struct wl_listener *listener, void *data)
661→{
662→	/* This event is forwarded by the cursor when a pointer emits an axis event,
