void wallpaper_cache_init(void)
{
	wl_list_init(&globalconf.wallpaper_cache);
	for (int i = 0; i < WALLPAPER_MAX_SCREENS; i++) {
		globalconf.current_wallpaper_per_screen[i] = NULL;
