void wallpaper_cache_cleanup(void)
{
	wallpaper_cache_entry_t *entry, *tmp;
	wl_list_for_each_safe(entry, tmp, &globalconf.wallpaper_cache, link) {
		wl_list_remove(&entry->link);
		if (entry->scene_node)
