 49→	if (strcasecmp(mod, "Control") == 0 || strcasecmp(mod, "Ctrl") == 0)
 50→		return BUTTON_MODIFIER_CTRL;
 51→	if (strcasecmp(mod, "Mod1") == 0 || strcasecmp(mod, "Alt") == 0)
 52→		return BUTTON_MODIFIER_ALT;
 53→	if (strcasecmp(mod, "Mod4") == 0 || strcasecmp(mod, "Super") == 0)
 54→		return BUTTON_MODIFIER_SUPER;
 55→	if (strcasecmp(mod, "Mod2") == 0) return BUTTON_MODIFIER_MOD2;
 56→	if (strcasecmp(mod, "Mod3") == 0) return BUTTON_MODIFIER_MOD3;
 57→	if (strcasecmp(mod, "Mod5") == 0) return BUTTON_MODIFIER_MOD5;
 58→	if (strcasecmp(mod, "Any") == 0) return BUTTON_MODIFIER_ANY;
 59→
 60→	return 0;
