482→static int
483→drawin_emit_button_signals(lua_State *L, int drawin_idx, drawin_t *drawin, uint32_t button,
484→                           uint32_t mods, bool is_press)
485→{
486→	const char *signal_name;
487→	uint32_t translated_button;
488→	uint16_t masked_mods;
489→	int matched;
490→	int i;
491→	button_t *btn;
492→	bool btn_matches;
493→	bool mods_match;
494→
495→	signal_name = is_press ? "press" : "release";
496→	translated_button = translate_button_code(button);
497→	matched = 0;
498→
499→	/* Mask modifiers to only the bits we care about (matches old button_matches() logic) */
500→	masked_mods = mods & 0xFF;
501→
502→	/* Iterate through button array */
503→	for (i = 0; i < drawin->buttons.len; i++) {
504→		btn = drawin->buttons.tab[i];
505→
506→
507→		/* Match button number (0 = any button) - use translated button code */
508→		btn_matches = (btn->button == 0 || btn->button == translated_button);
509→
510→		/* Match modifiers (BUTTON_MODIFIER_ANY = any modifiers, otherwise exact match)
511→		 * This matches AwesomeWM's logic: modifiers == 0 means "NO modifiers", not "any modifiers" */
512→		mods_match = (btn->modifiers == BUTTON_MODIFIER_ANY || btn->modifiers == masked_mods);
513→
514→		if (btn_matches && mods_match) {
515→
516→			/* Push button object from drawin's uservalue table */
517→			luaA_object_push_item(L, drawin_idx, btn);
518→
519→			/* Emit press/release signal on button object (no args) */
520→			luaA_awm_object_emit_signal(L, -1, signal_name, 0);
521→
522→			/* Pop button object */
523→			lua_pop(L, 1);
524→
525→			matched++;
526→		}
527→	}
528→
529→	return matched;
530→}
