532→/** Check drawin button array from C code (AwesomeWM-compatible implementation)
533→ * This implements the two-stage button event handling pattern from AwesomeWM:
534→ * Stage 1: Emit button::press/release on drawable with coordinates
535→ * Stage 2: Emit press/release on matching button objects
536→ *
537→ * \param drawin_ptr Drawin pointer
538→ * \param x Relative X coordinate (drawin-relative)
539→ * \param y Relative Y coordinate (drawin-relative)
540→ * \param button Button code
541→ * \param mods Modifier mask
542→ * \param is_press true for button press, false for release
543→ * \return 1 if handled, 0 otherwise
544→ */
545→int
546→luaA_drawin_button_check(void *drawin_ptr, int x, int y, uint32_t button,
547→                         uint32_t mods, bool is_press)
548→{
549→	drawin_t *drawin;
550→	lua_State *L;
551→	int matched;
552→
553→	drawin = (drawin_t *)drawin_ptr;
554→	L = globalconf_get_lua_State();
555→
556→	if (!drawin) {
557→		return 0;
558→	}
559→
560→	/* Push drawin object to stack */
561→	luaA_object_push(L, drawin);
