	xytonode(cursor->x, cursor->y, NULL, &c, NULL, &drawin, &titlebar_drawable, NULL, NULL);

	if (drawin) {
		/* Scroll on drawin (wibox) */
		rel_x = (int)cursor->x - drawin->x;
