		/* Emit press then release (scroll is instantaneous) */
		luaA_drawin_button_check(drawin, rel_x, rel_y, button, CLEANMASK(mods), true);
		luaA_drawin_button_check(drawin, rel_x, rel_y, button, CLEANMASK(mods), false);
